PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('solo','team')), rate INTEGER NOT NULL DEFAULT 0, logo TEXT NOT NULL DEFAULT '', storage TEXT);
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), password TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,email), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(token TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member')), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS projects(company_id TEXT NOT NULL REFERENCES companies(id), code TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, rate INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(company_id,code));
CREATE TABLE IF NOT EXISTS activities(company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('DIRECT','INDIRECT')), PRIMARY KEY(company_id,name));
CREATE TABLE IF NOT EXISTS entries(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, member_id TEXT NOT NULL, project TEXT NOT NULL, date TEXT NOT NULL, activity TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', start TEXT NOT NULL DEFAULT '', end TEXT NOT NULL DEFAULT '', minutes INTEGER NOT NULL CHECK(minutes BETWEEN 1 AND 1440), km REAL NOT NULL DEFAULT 0 CHECK(km>=0), from_pc TEXT NOT NULL DEFAULT '', to_pc TEXT NOT NULL DEFAULT '', return_trip INTEGER NOT NULL DEFAULT 1, legacy_billed INTEGER NOT NULL DEFAULT 0 CHECK(legacy_billed BETWEEN 0 AND minutes), rev INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(company_id,member_id) REFERENCES members(company_id,id), FOREIGN KEY(company_id,project) REFERENCES projects(company_id,code), FOREIGN KEY(company_id,activity) REFERENCES activities(company_id,name), UNIQUE(company_id,id));
CREATE INDEX IF NOT EXISTS entries_company_date ON entries(company_id,date,member_id);
CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, project TEXT NOT NULL, date TEXT NOT NULL, method TEXT NOT NULL CHECK(method IN ('hours','fixed','percentage')), amount INTEGER NOT NULL CHECK(amount>=0), base INTEGER NOT NULL DEFAULT 0, percentage REAL NOT NULL DEFAULT 0, reference TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','void')), FOREIGN KEY(company_id,project) REFERENCES projects(company_id,code), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS allocations(company_id TEXT NOT NULL, claim_id TEXT NOT NULL, entry_id TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes>0), PRIMARY KEY(claim_id,entry_id), FOREIGN KEY(company_id,claim_id) REFERENCES claims(company_id,id), FOREIGN KEY(company_id,entry_id) REFERENCES entries(company_id,id));
CREATE TRIGGER IF NOT EXISTS allocation_limit BEFORE INSERT ON allocations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM entries e JOIN claims c ON c.company_id=e.company_id AND c.project=e.project WHERE e.company_id=NEW.company_id AND e.id=NEW.entry_id AND c.id=NEW.claim_id AND c.status='draft' AND e.minutes-e.legacy_billed-COALESCE((SELECT SUM(a.minutes) FROM allocations a JOIN claims d ON d.id=a.claim_id WHERE a.entry_id=e.id AND d.status!='void'),0)>=NEW.minutes) THEN RAISE(ABORT,'allocation exceeds remaining minutes or wrong project') END;
END;
CREATE TRIGGER IF NOT EXISTS entry_update_guard BEFORE UPDATE ON entries BEGIN
 SELECT CASE WHEN NEW.minutes < NEW.legacy_billed+COALESCE((SELECT SUM(a.minutes) FROM allocations a JOIN claims c ON c.id=a.claim_id WHERE a.entry_id=OLD.id AND c.status!='void'),0) OR (NEW.project!=OLD.project AND EXISTS(SELECT 1 FROM allocations a JOIN claims c ON c.id=a.claim_id WHERE a.entry_id=OLD.id AND c.status!='void')) THEN RAISE(ABORT,'entry already billed') END;
END;
CREATE TRIGGER IF NOT EXISTS entry_delete_guard BEFORE DELETE ON entries WHEN OLD.legacy_billed>0 OR EXISTS(SELECT 1 FROM allocations a WHERE a.entry_id=OLD.id) BEGIN SELECT RAISE(ABORT,'entry has billing history'); END;
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), member_id TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_limits(key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS company_modules(company_id TEXT PRIMARY KEY REFERENCES companies(id), clients INTEGER NOT NULL DEFAULT 0 CHECK(clients IN (0,1)), budgets INTEGER NOT NULL DEFAULT 0 CHECK(budgets IN (0,1)), warnings INTEGER NOT NULL DEFAULT 0 CHECK(warnings IN (0,1)));
CREATE TABLE IF NOT EXISTS member_preferences(member_id TEXT PRIMARY KEY REFERENCES members(id), stopwatch INTEGER NOT NULL DEFAULT 0 CHECK(stopwatch IN (0,1)), repeat_entry INTEGER NOT NULL DEFAULT 0 CHECK(repeat_entry IN (0,1)), dark INTEGER NOT NULL DEFAULT 0 CHECK(dark IN (0,1)));
CREATE TABLE IF NOT EXISTS clients(company_id TEXT NOT NULL REFERENCES companies(id), id TEXT NOT NULL, name TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(company_id,id));
CREATE TABLE IF NOT EXISTS project_extras(company_id TEXT NOT NULL, project TEXT NOT NULL, client_id TEXT, budget_minutes INTEGER NOT NULL DEFAULT 0 CHECK(budget_minutes>=0), budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(budget_cents>=0), PRIMARY KEY(company_id,project), FOREIGN KEY(company_id,project) REFERENCES projects(company_id,code), FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id));
CREATE TABLE IF NOT EXISTS optional_schema_v1(id INTEGER PRIMARY KEY CHECK(id=1));
INSERT OR IGNORE INTO optional_schema_v1(id) VALUES(1);

-- Unverified registrations have no company/member access until confirmed.
CREATE TABLE IF NOT EXISTS pending_signups(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,company TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('solo','team')),email TEXT NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pending_signups_expiry ON pending_signups(expires);
